#[test]
fn sqlite_snapshot_step_cohort_semantic_words_match_independent_sqlite_dataview() {
    use std::io::Write;
    use std::process::{Command, Stdio};
    let corpus: serde_json::Value = serde_json::from_str(include_str!("../../../../../../../../../../📇️registry/🧬️contract/📐️part21/🧫️fixtures/🚦️sqlite-cohort/🔣️.json")).unwrap();
    let words: Vec<String> = corpus["binary64Words"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect();
    let bits: Vec<u64> = words.iter().map(|v|u64::from_str_radix(v,16).unwrap()).collect();
    let mut snapshot = cohort_step(String::new());
    snapshot.schema = "literal owned schema".into();
    snapshot.entities[0].args = bits.iter().map(|word|StepValue::Real(f64::from_bits(*word))).collect();
    let bytes = export_sqlite_database(&project(&snapshot), SqliteDatabaseLimits::default(), &mut |_|true).unwrap();
    let script = r#"import{Database}from'bun:sqlite';const expected=EXPECTED_WORDS;const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const rows=db.query("SELECT real_value,real_bits,real_class FROM step_value WHERE kind='real' ORDER BY id").safeIntegers(true).all();if(rows.length!==expected.length)throw Error('count');for(let i=0;i<rows.length;i++){const row=rows[i],bits=BigInt('0x'+expected[i]);if(BigInt.asUintN(64,row.real_bits)!==bits)throw Error('word');const view=new DataView(new ArrayBuffer(8));view.setBigUint64(0,bits,true);const number=view.getFloat64(0,true);const kind=Number.isNaN(number)?'nan':number===Infinity?'positiveInfinity':number===-Infinity?'negativeInfinity':'finite';if(row.real_class!==kind||(kind==='nan'?row.real_value!==null:row.real_value!==number))throw Error('query value/class');}await Bun.write(Bun.stdout,db.serialize());db.close();"#.replace("EXPECTED_WORDS", &serde_json::to_string(&words).unwrap());
    let mut child = Command::new("bun").args(["-e",&script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();
    child.stdin.take().unwrap().write_all(&bytes).unwrap();
    let result = child.wait_with_output().unwrap();
    assert!(result.status.success(), "{}", String::from_utf8_lossy(&result.stderr));
    let restored = restore(&import_sqlite_database(&result.stdout, SqliteDatabaseLimits::default(), &mut |_|true).unwrap()).unwrap();
    assert_eq!(restored.schema,snapshot.schema);
    assert_eq!(restored.entities[0].args.iter().map(|v|match v { StepValue::Real(value)=>value.to_bits(),_=>panic!("real tag") }).collect::<Vec<_>>(),bits);
}

