fn sqlite_snapshot_ifc2x3_independent_sqlite_decimal_and_edm_field_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(db.query('SELECT kind FROM ifc2x3_value GROUP BY kind').all().length!==9||db.query('SELECT decimal_scale FROM ifc2x3_value WHERE decimal_scale=4294967295').get().decimal_scale!==4294967295)throw Error('decimal');const{importSqliteDatabase,exportSqliteDatabase}=await import(process.argv[1]);const{ifc2x3SnapshotFromSqliteDatabase,ifc2x3SnapshotToSqliteDatabase}=await import(process.argv[2]);const other=Database.deserialize(await exportSqliteDatabase(await ifc2x3SnapshotToSqliteDatabase(await ifc2x3SnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize())))));const canonical=value=>JSON.stringify(value,(_,v)=>typeof v==='bigint'?v.toString():v);for(const table of['ifc2x3_document','ifc2x3_header','ifc2x3_file_description_argument','ifc2x3_file_name_argument','ifc2x3_file_schema_argument','ifc2x3_instance','ifc2x3_entity_type','ifc2x3_entity_argument','ifc2x3_value','ifc2x3_list_element','ifc2x3_typed_argument','ifc2x3_edm_preamble'])if(canonical(db.query('SELECT * FROM '+table+' ORDER BY id').safeIntegers(true).all())!==canonical(other.query('SELECT * FROM '+table+' ORDER BY id').safeIntegers(true).all()))throw Error('Rust/TypeScript IFC2x3 field mismatch '+table);other.close();db.query(\"UPDATE ifc2x3_edm_preamble SET options='SQL_EDIT'\").run();await Bun.write(Bun.stdout,db.serialize());db.close();";let framework=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🟦️.ts").canonicalize().unwrap();let artifact=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../🟦️.ts").canonicalize().unwrap();let mut child=Command::new("bun").args(["-e",script,framework.to_str().unwrap(),artifact.to_str().unwrap()]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));assert_eq!(restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap().edm_preamble.unwrap().options,"SQL_EDIT");}

